"use client"

import * as React from "react"
import { Slider as SliderPrimitive } from "@base-ui/react/slider"

import { cn } from "@/lib/utils"

// Amber Glass Slider: recessed well track; the range fill and thumb carry the
// same amber material as the primary Button (gradient + rim + glow).

const Slider = React.forwardRef<HTMLDivElement, SliderPrimitive.Root.Props>(
  ({ className, defaultValue, value, min = 0, max = 100, ...props }, ref) => {
    const _values = Array.isArray(value)
      ? value
      : Array.isArray(defaultValue)
        ? defaultValue
        : [min, max]

    return (
      <SliderPrimitive.Root
        data-slot="slider"
        ref={ref}
        thumbAlignment="edge"
        defaultValue={defaultValue}
        value={value}
        min={min}
        max={max}
        className={cn("relative w-full", className)}
        {...props}
      >
        <SliderPrimitive.Control className="flex w-full touch-none select-none items-center">
          <SliderPrimitive.Track
            data-slot="slider-track"
            className={cn(
              "relative h-1.5 w-full grow overflow-hidden rounded-full",
              "bg-[var(--ag-well)] border border-[color:var(--ag-border)] shadow-[var(--shadow-well)]"
            )}
          >
            <SliderPrimitive.Indicator
              data-slot="slider-range"
              className={cn(
                "absolute h-full",
                "bg-[image:var(--ag-primary-grad)]",
                "shadow-[inset_0_0.0625rem_0_oklch(1_0_0/0.32),0_0_0.625rem_oklch(0.69_0.195_42/0.4)]"
              )}
            />
          </SliderPrimitive.Track>
          {Array.from({ length: _values.length }, (_, index) => (
            <SliderPrimitive.Thumb
              data-slot="slider-thumb" key={index}
              className={cn(
                "block h-4 w-4 rounded-full",
                "bg-[image:var(--ag-primary-grad)]",
                "shadow-[var(--shadow-primary)]",
                "transition-shadow duration-fast ease-out",
                "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/60 focus-visible:ring-offset-2 focus-visible:ring-offset-background",
                "data-disabled:pointer-events-none data-disabled:opacity-50"
              )}
            />
          ))}
        </SliderPrimitive.Control>
      </SliderPrimitive.Root>
    )
  }
)
Slider.displayName = "Slider"

export { Slider }
